-- AulaTech. Datos ficticios para prácticas de DWES. MySQL 8 / MariaDB.
-- Importar una sola vez en una base nueva. No elimina tablas ni bases existentes.
-- Usuarios: admin01, admin02, user03 ... user20. Contraseña = nombre de usuario.
-- Hash bcrypt con sal individual; verificar en PHP con password_verify().
CREATE DATABASE IF NOT EXISTS aulatech CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE aulatech;
CREATE TABLE users (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(30) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    full_name VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    role ENUM('user', 'admin') NOT NULL DEFAULT 'user'
) ENGINE=InnoDB;
CREATE TABLE articles (
    id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    description TEXT NOT NULL,
    category VARCHAR(50) NOT NULL,
    price DECIMAL(10,2) NOT NULL,
    stock INT UNSIGNED NOT NULL DEFAULT 0,
    CHECK (price >= 0)
) ENGINE=InnoDB;
START TRANSACTION;
COMMIT;
-- Comprobación: deben obtenerse 20 usuarios y 500 artículos.
SELECT COUNT(*) AS total_users FROM users;
SELECT COUNT(*) AS total_articles FROM articles;